-- ============================================================================
-- B5 FOLLOW-ON W1, D4 PART C: the open-book label on the welldata capstone
-- brief.
--
-- WHY. A lesson or a panel's opening view prints the answers these capstones
-- grade (docs/graded-field-audit/README.md finding 3; FOLLOW-ON-PROGRAMME.md
-- section 3). Until W5 re-cases or strips them, the brief says so. The label is
-- the brief's first sentence; the rest of the prompt is unchanged. The same
-- note heads the tier's capstone lesson (NextGen zip).
--
-- beginner: every graded figure(s) printed; section 3 pick A (re-case)
-- intermediate: every graded figure(s) printed; section 3 pick A (re-case)
-- advanced: every graded figure(s) printed; section 3 pick A (re-case)
--
-- THE LABEL:
--   Open book: the figures this capstone grades can be read in this tier's
--   lessons or on a panel as it opens, so for now it checks that you can find,
--   read and report each one correctly. A later update moves it to a case of its
--   own.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its post-20261024a value exactly, before and after, so no answer
-- grades differently and no attempt guard is needed.
--
-- GUARDS. Each prompt must hold its post-20261024a text (md5, rewritten) or
-- its labelled text (left alone). Anything else raises and the file rolls
-- back. Runs after 20261024a_w1_*. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
  v_s2       text;
begin
  -- welldata / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'welldata' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w1 open-book welldata refused: welldata/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '413363c4d3aaa8ccfcd17696a5a18a9d' and fields = '[{"key": "basic_n_samples", "tol": 0, "unit": "count", "label": "basic_20: depth samples", "expected": 301}, {"key": "basic_gr_nulls", "tol": 0, "unit": "count", "label": "basic_20: GR null samples", "expected": 8}, {"key": "basic_gr_mean", "tol": 0.05, "unit": "GAPI", "label": "basic_20: mean GR (finite samples)", "expected": 64.92719962459895}, {"key": "feet_step_m", "tol": 0.001, "unit": "m", "label": "feet_20: depth step, converted", "expected": 0.6096}, {"key": "nullheavy_nphi_nulls", "tol": 0, "unit": "count", "label": "nullheavy_20: NPHI null samples", "expected": 201}, {"key": "wrapped_n_samples", "tol": 0, "unit": "count", "label": "wrapped_12: depth samples", "expected": 161}]'::jsonb then 'old'
              when md5(prompt) = 'f362ed27e7d8766e7e51dcf1ca0e5e6e' and fields = '[{"key": "basic_n_samples", "tol": 0, "unit": "count", "label": "basic_20: depth samples", "expected": 301}, {"key": "basic_gr_nulls", "tol": 0, "unit": "count", "label": "basic_20: GR null samples", "expected": 8}, {"key": "basic_gr_mean", "tol": 0.05, "unit": "GAPI", "label": "basic_20: mean GR (finite samples)", "expected": 64.92719962459895}, {"key": "feet_step_m", "tol": 0.001, "unit": "m", "label": "feet_20: depth step, converted", "expected": 0.6096}, {"key": "nullheavy_nphi_nulls", "tol": 0, "unit": "count", "label": "nullheavy_20: NPHI null samples", "expected": 201}, {"key": "wrapped_n_samples", "tol": 0, "unit": "count", "label": "wrapped_12: depth samples", "expected": 161}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'welldata' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w1 open-book welldata refused: welldata/beginner matches neither its published form (prompt md5 413363c4d3aaa8ccfcd17696a5a18a9d) nor its W1 form (prompt md5 f362ed27e7d8766e7e51dcf1ca0e5e6e), with the fields this file was generated against';
  end if;

  -- welldata / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'welldata' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w1 open-book welldata refused: welldata/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '88ea368e2ada542624915ddf79b41c04' and fields = '[{"key": "start_md_m", "tol": 0.01, "unit": "m", "label": "feet_20: start depth (converted)", "expected": 1493.52001953125}, {"key": "stop_md_m", "tol": 0.01, "unit": "m", "label": "feet_20: stop depth (converted)", "expected": 1584.9599609375}, {"key": "step_m", "tol": 0.001, "unit": "m", "label": "feet_20: depth step (converted)", "expected": 0.609619140625}, {"key": "converted_curves", "tol": 0, "unit": "count", "label": "feet_20: curves unit-converted", "expected": 2}, {"key": "recognized_kinds", "tol": 0, "unit": "count", "label": "feet_20: curve kinds recognised", "expected": 4}, {"key": "irregular_samples", "tol": 0, "unit": "count", "label": "irregular_20: depth samples", "expected": 121}]'::jsonb then 'old'
              when md5(prompt) = 'f1f9dc40f987775a462d8673843a6460' and fields = '[{"key": "start_md_m", "tol": 0.01, "unit": "m", "label": "feet_20: start depth (converted)", "expected": 1493.52001953125}, {"key": "stop_md_m", "tol": 0.01, "unit": "m", "label": "feet_20: stop depth (converted)", "expected": 1584.9599609375}, {"key": "step_m", "tol": 0.001, "unit": "m", "label": "feet_20: depth step (converted)", "expected": 0.609619140625}, {"key": "converted_curves", "tol": 0, "unit": "count", "label": "feet_20: curves unit-converted", "expected": 2}, {"key": "recognized_kinds", "tol": 0, "unit": "count", "label": "feet_20: curve kinds recognised", "expected": 4}, {"key": "irregular_samples", "tol": 0, "unit": "count", "label": "irregular_20: depth samples", "expected": 121}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'welldata' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w1 open-book welldata refused: welldata/intermediate matches neither its published form (prompt md5 88ea368e2ada542624915ddf79b41c04) nor its W1 form (prompt md5 f1f9dc40f987775a462d8673843a6460), with the fields this file was generated against';
  end if;

  -- welldata / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'welldata' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 open-book welldata refused: welldata/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '14b40c32d5f7f82929ffd704ab669bf8' and fields = '[{"key": "campaign_curves", "tol": 0, "unit": "count", "label": "Curves imported across the campaign", "expected": 24}, {"key": "converted_files", "tol": 0, "unit": "count", "label": "Files needing depth unit conversion", "expected": 1}, {"key": "dead_curves", "tol": 0, "unit": "count", "label": "Dead curves detected", "expected": 1}, {"key": "uniform_files", "tol": 0, "unit": "count", "label": "Files with a uniform depth step", "expected": 5}, {"key": "wrapped_samples", "tol": 0, "unit": "count", "label": "Depth samples in wrapped_12", "expected": 161}, {"key": "nullheavy_nulls", "tol": 0, "unit": "count", "label": "Flagged nulls in nullheavy_20", "expected": 272}]'::jsonb then 'old'
              when md5(prompt) = 'afcf8eee7d3e7053b92c405d350fd513' and fields = '[{"key": "campaign_curves", "tol": 0, "unit": "count", "label": "Curves imported across the campaign", "expected": 24}, {"key": "converted_files", "tol": 0, "unit": "count", "label": "Files needing depth unit conversion", "expected": 1}, {"key": "dead_curves", "tol": 0, "unit": "count", "label": "Dead curves detected", "expected": 1}, {"key": "uniform_files", "tol": 0, "unit": "count", "label": "Files with a uniform depth step", "expected": 5}, {"key": "wrapped_samples", "tol": 0, "unit": "count", "label": "Depth samples in wrapped_12", "expected": 161}, {"key": "nullheavy_nulls", "tol": 0, "unit": "count", "label": "Flagged nulls in nullheavy_20", "expected": 272}]'::jsonb then 'new'
              else 'other' end
    into v_s2 from public.academy_capstones where app_slug = 'welldata' and tier = 'advanced' and active;
  if v_s2 = 'other' then
    raise exception 'w1 open-book welldata refused: welldata/advanced matches neither its published form (prompt md5 14b40c32d5f7f82929ffd704ab669bf8) nor its W1 form (prompt md5 afcf8eee7d3e7053b92c405d350fd513), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' and v_s1 = 'new' and v_s2 = 'new' then
    raise notice 'w1 open-book welldata: 0 of 3 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 open-book welldata refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Load each of the six teaching LAS files in the app and read the QC panel. Report the requested values exactly as the parser shows them: sample and null counts are integers; report the mean GR over finite samples; convert the feet_20 depth step to metres.',
           fields = '[{"key": "basic_n_samples", "tol": 0, "unit": "count", "label": "basic_20: depth samples", "expected": 301}, {"key": "basic_gr_nulls", "tol": 0, "unit": "count", "label": "basic_20: GR null samples", "expected": 8}, {"key": "basic_gr_mean", "tol": 0.05, "unit": "GAPI", "label": "basic_20: mean GR (finite samples)", "expected": 64.92719962459895}, {"key": "feet_step_m", "tol": 0.001, "unit": "m", "label": "feet_20: depth step, converted", "expected": 0.6096}, {"key": "nullheavy_nphi_nulls", "tol": 0, "unit": "count", "label": "nullheavy_20: NPHI null samples", "expected": 201}, {"key": "wrapped_n_samples", "tol": 0, "unit": "count", "label": "wrapped_12: depth samples", "expected": 161}]'::jsonb
     where app_slug = 'welldata' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book welldata refused: welldata/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'f362ed27e7d8766e7e51dcf1ca0e5e6e' and fields = '[{"key": "basic_n_samples", "tol": 0, "unit": "count", "label": "basic_20: depth samples", "expected": 301}, {"key": "basic_gr_nulls", "tol": 0, "unit": "count", "label": "basic_20: GR null samples", "expected": 8}, {"key": "basic_gr_mean", "tol": 0.05, "unit": "GAPI", "label": "basic_20: mean GR (finite samples)", "expected": 64.92719962459895}, {"key": "feet_step_m", "tol": 0.001, "unit": "m", "label": "feet_20: depth step, converted", "expected": 0.6096}, {"key": "nullheavy_nphi_nulls", "tol": 0, "unit": "count", "label": "nullheavy_20: NPHI null samples", "expected": 201}, {"key": "wrapped_n_samples", "tol": 0, "unit": "count", "label": "wrapped_12: depth samples", "expected": 161}]'::jsonb) from public.academy_capstones where app_slug = 'welldata' and tier = 'beginner' and active) is not true then
    raise exception 'w1 open-book welldata refused: welldata/beginner does not read back as its W1 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Run the full import pipeline on feet_20.las and read the import panel: the depth range and step converted to metres, how many curves needed unit conversion, how many curve kinds the importer recognised, and the number of depth samples in irregular_20, the one teaching file whose depth step is NOT uniform.',
           fields = '[{"key": "start_md_m", "tol": 0.01, "unit": "m", "label": "feet_20: start depth (converted)", "expected": 1493.52001953125}, {"key": "stop_md_m", "tol": 0.01, "unit": "m", "label": "feet_20: stop depth (converted)", "expected": 1584.9599609375}, {"key": "step_m", "tol": 0.001, "unit": "m", "label": "feet_20: depth step (converted)", "expected": 0.609619140625}, {"key": "converted_curves", "tol": 0, "unit": "count", "label": "feet_20: curves unit-converted", "expected": 2}, {"key": "recognized_kinds", "tol": 0, "unit": "count", "label": "feet_20: curve kinds recognised", "expected": 4}, {"key": "irregular_samples", "tol": 0, "unit": "count", "label": "irregular_20: depth samples", "expected": 121}]'::jsonb
     where app_slug = 'welldata' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book welldata refused: welldata/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'f1f9dc40f987775a462d8673843a6460' and fields = '[{"key": "start_md_m", "tol": 0.01, "unit": "m", "label": "feet_20: start depth (converted)", "expected": 1493.52001953125}, {"key": "stop_md_m", "tol": 0.01, "unit": "m", "label": "feet_20: stop depth (converted)", "expected": 1584.9599609375}, {"key": "step_m", "tol": 0.001, "unit": "m", "label": "feet_20: depth step (converted)", "expected": 0.609619140625}, {"key": "converted_curves", "tol": 0, "unit": "count", "label": "feet_20: curves unit-converted", "expected": 2}, {"key": "recognized_kinds", "tol": 0, "unit": "count", "label": "feet_20: curve kinds recognised", "expected": 4}, {"key": "irregular_samples", "tol": 0, "unit": "count", "label": "irregular_20: depth samples", "expected": 121}]'::jsonb) from public.academy_capstones where app_slug = 'welldata' and tier = 'intermediate' and active) is not true then
    raise exception 'w1 open-book welldata refused: welldata/intermediate does not read back as its W1 form';
  end if;

  if v_s2 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Run the full import pipeline on every teaching file and read the campaign panel: total curves imported (depth excluded), files needing unit conversion, dead curves detected, files with a uniform depth step, samples parsed from the wrapped LAS 1.2 file, and total flagged nulls in nullheavy_20.',
           fields = '[{"key": "campaign_curves", "tol": 0, "unit": "count", "label": "Curves imported across the campaign", "expected": 24}, {"key": "converted_files", "tol": 0, "unit": "count", "label": "Files needing depth unit conversion", "expected": 1}, {"key": "dead_curves", "tol": 0, "unit": "count", "label": "Dead curves detected", "expected": 1}, {"key": "uniform_files", "tol": 0, "unit": "count", "label": "Files with a uniform depth step", "expected": 5}, {"key": "wrapped_samples", "tol": 0, "unit": "count", "label": "Depth samples in wrapped_12", "expected": 161}, {"key": "nullheavy_nulls", "tol": 0, "unit": "count", "label": "Flagged nulls in nullheavy_20", "expected": 272}]'::jsonb
     where app_slug = 'welldata' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book welldata refused: welldata/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'afcf8eee7d3e7053b92c405d350fd513' and fields = '[{"key": "campaign_curves", "tol": 0, "unit": "count", "label": "Curves imported across the campaign", "expected": 24}, {"key": "converted_files", "tol": 0, "unit": "count", "label": "Files needing depth unit conversion", "expected": 1}, {"key": "dead_curves", "tol": 0, "unit": "count", "label": "Dead curves detected", "expected": 1}, {"key": "uniform_files", "tol": 0, "unit": "count", "label": "Files with a uniform depth step", "expected": 5}, {"key": "wrapped_samples", "tol": 0, "unit": "count", "label": "Depth samples in wrapped_12", "expected": 161}, {"key": "nullheavy_nulls", "tol": 0, "unit": "count", "label": "Flagged nulls in nullheavy_20", "expected": 272}]'::jsonb) from public.academy_capstones where app_slug = 'welldata' and tier = 'advanced' and active) is not true then
    raise exception 'w1 open-book welldata refused: welldata/advanced does not read back as its W1 form';
  end if;

  raise notice 'w1 open-book welldata: % of 3 row(s) written, % already applied', v_written, 3 - v_written;
end $$;
